fn main() -> Result<(), Box<dyn Error>> {
    let output_path = common::output_path("hyperlinks-and-names-sample.xlsx");

    let mut workbook = Workbook::new();
    let scoped_sheet_index;
    {
        let mut worksheets = workbook.get_worksheets_mut();
        scoped_sheet_index = worksheets.add("Scoped Sheet")?;
        {
            let scoped_sheet = worksheets.get(scoped_sheet_index)?;
            scoped_sheet.get_cells_mut().get("B2")?.put_value_i32(5)?;
        }
        {
            let links_sheet = worksheets.get(0)?;
            links_sheet.set_name("Links")?;
            links_sheet
                .get_cells_mut()
                .get("A1")?
                .put_value_string("Docs")?;
            links_sheet
                .get_cells_mut()
                .get("B2")?
                .put_value_string("Jump")?;
            links_sheet
                .get_cells_mut()
                .get("C4")?
                .put_value_string("Mail")?;

            {
                let mut hyperlinks = links_sheet.get_hyperlinks();
                let external_index = hyperlinks.add("A1", 1, 1, "https://example.com/docs?q=1")?;
                let mut external_link = hyperlinks
                    .get(external_index)
                    .expect("hyperlink should exist");
                external_link.set_text_to_display("Docs");
                external_link.set_screen_tip("External docs");

                let internal_index = hyperlinks.add("B2", 1, 1, "'Scoped Sheet'!B2")?;
                let mut internal_link = hyperlinks
                    .get(internal_index)
                    .expect("hyperlink should exist");
                internal_link.set_text_to_display("Jump");
                internal_link.set_screen_tip("Jump to scoped sheet");

                let mail_index = hyperlinks.add("C4", 2, 2, "mailto:test@example.com")?;
                let mut mail_link = hyperlinks.get(mail_index).expect("hyperlink should exist");
                mail_link.set_text_to_display("Mail");
                mail_link.set_screen_tip("Send mail");
            }

            // Apply the standard hyperlink text style (blue, underlined) to linked cells.
            let mut cells = links_sheet.get_cells_mut();
            for address in ["A1", "B2", "C4"] {
                let mut cell = cells.get(address)?;
                let mut style = cell.get_style();
                let font = style.get_font_mut();
                font.set_color(HYPERLINK_COLOR);
                font.set_underline(FontUnderlineType::Single);
                cell.set_style(style)?;
            }
        }
    }

    {
        let mut defined_names = workbook.get_defined_names();
        let global_index = defined_names.add("GlobalRange", "='Links'!$A$1:$D$5")?;
        let mut global_name = defined_names
            .get(global_index)
            .expect("defined name should exist");
        global_name.set_hidden(true);
        global_name.set_comment("Primary sample range");

        let local_index = defined_names.add_with_scope(
            "ScopedCell",
            "'Scoped Sheet'!$B$2",
            Some(scoped_sheet_index),
        )?;
        let mut local_name = defined_names
            .get(local_index)
            .expect("defined name should exist");
        local_name.set_comment("Sheet-scoped name");
    }

    workbook.save(&output_path)?;

    let mut loaded = Workbook::load_xlsx(&output_path)?;
    let (hyperlink_count, first, second) = {
        let mut sheets = loaded.get_worksheets_mut();
        let links_sheet = sheets.get_by_name("Links")?;
        let mut hyperlinks = links_sheet.get_hyperlinks();
        let count = hyperlinks.count();
        let first = {
            let hyperlink = hyperlinks.get(0).expect("hyperlink");
            (hyperlink.get_address().to_string(), hyperlink.get_area())
        };
        let second = {
            let hyperlink = hyperlinks.get(1).expect("hyperlink");
            (hyperlink.get_address().to_string(), hyperlink.get_area())
        };
        (count, first, second)
    };
    let mut defined_names = loaded.get_defined_names();

    println!("Saved: {}", output_path.display());
    println!("Hyperlinks: {}", hyperlink_count);
    println!("First hyperlink: {} / {}", first.0, first.1);
    println!("Second hyperlink: {} / {}", second.0, second.1);
    println!("Defined names: {}", defined_names.count());
    println!(
        "Global name formula: {}",
        defined_names.get(0).expect("name").get_formula()
    );
    println!(
        "Local name scope: {}",
        defined_names
            .get(1)
            .expect("name")
            .get_local_sheet_index()
            .map(|value| value as i32)
            .unwrap_or(-1)
    );

    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let output_path = common::output_path("listobjects-sample.xlsx");

    let mut workbook = Workbook::new();
    {
        let mut worksheets = workbook.get_worksheets_mut();
        let sheet = worksheets.get(0)?;
        sheet.set_name("Data")?;
        let mut cells = sheet.get_cells_mut();

        for (address, value) in [
            ("A1", "Product"),
            ("B1", "Category"),
            ("C1", "Price"),
            ("D1", "Quantity"),
            ("A2", "Laptop"),
            ("B2", "Electronics"),
            ("A3", "Mouse"),
            ("B3", "Electronics"),
            ("A4", "Desk Chair"),
            ("B4", "Furniture"),
            ("A5", "Monitor"),
            ("B5", "Electronics"),
        ] {
            cells.get(address)?.put_value_string(value)?;
        }

        cells.get("C2")?.put_value_f64(999.99)?;
        cells.get("D2")?.put_value_i32(50)?;
        cells.get("C3")?.put_value_f64(29.99)?;
        cells.get("D3")?.put_value_i32(200)?;
        cells.get("C4")?.put_value_f64(149.99)?;
        cells.get("D4")?.put_value_i32(75)?;
        cells.get("C5")?.put_value_f64(349.99)?;
        cells.get("D5")?.put_value_i32(100)?;
        // Note: the totals row (row 6) is intentionally left empty here. It is
        // filled in automatically from the column totals declarations below, so
        // the library emits the structured SUBTOTAL formula that Excel requires.

        let mut tables = sheet.get_list_objects();
        let table_index = tables.add_a1("A1", "D5", true)?;
        let mut table = tables
            .get(table_index as usize)
            .expect("table should exist");
        table.set_display_name("Products")?;
        table.set_comment("Product inventory table");
        table.set_table_style_type(TableStyleType::TableStyleMedium2);
        table.set_show_table_style_first_column(true);
        table.set_show_table_style_last_column(true);
        table.set_show_table_style_row_stripes(true);
        table.set_show_totals(true);

        // Describe the totals row so Excel can reconcile it with the cells above:
        // a "Total" label under the first column and a SUM over the Quantity column.
        {
            let mut columns = table.get_list_columns();
            columns
                .get(0)
                .expect("first column should exist")
                .set_totals_row_label("Total");
            columns
                .get(3)
                .expect("quantity column should exist")
                .set_totals_calculation(TotalsCalculation::Sum);
        }
    }

    workbook.save(&output_path)?;

    let mut loaded = Workbook::load_xlsx(&output_path)?;
    let mut sheets = loaded.get_worksheets_mut();
    let sheet = sheets.get_by_name("Data")?;
    let mut tables = sheet.get_list_objects();
    let table_count = tables.count();
    let (
        table_name,
        table_comment,
        table_style,
        show_headers,
        show_totals,
        column_count,
        first_column_name,
    ) = {
        let mut table = tables.get_by_name("Products").expect("table should exist");
        let table_name = table.get_display_name().to_string();
        let table_comment = table.get_comment().to_string();
        let table_style = table.get_table_style_type();
        let show_headers = table.get_show_header_row();
        let show_totals = table.get_show_totals();
        let mut columns = table.get_list_columns();
        let column_count = columns.count();
        let first_column_name = columns
            .get(0)
            .expect("column should exist")
            .get_name()
            .to_string();
        (
            table_name,
            table_comment,
            table_style,
            show_headers,
            show_totals,
            column_count,
            first_column_name,
        )
    };

    println!("Saved: {}", output_path.display());
    println!("Table count: {}", table_count);
    println!("Table name: {}", table_name);
    println!("Table comment: {}", table_comment);
    println!("Table style: {:?}", table_style);
    println!("Show headers: {}", show_headers);
    println!("Show totals: {}", show_totals);
    println!("Column count: {}", column_count);
    println!("First column: {}", first_column_name);

    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let valid_path = common::output_path("loading-sample.xlsx");

    let mut workbook = Workbook::new();
    {
        let mut worksheets = workbook.get_worksheets_mut();
        let sheet = worksheets.get(0)?;
        let mut cells = sheet.get_cells_mut();

        cells.get("A1")?.put_value_string("Item")?;
        cells.get("B1")?.put_value_string("Quantity")?;
        cells.get("C1")?.put_value_string("Active")?;
        cells.get("A2")?.put_value_string("Apples")?;
        cells.get("B2")?.put_value_i32(12)?;
        cells.get("C2")?.put_value_bool(true)?;
        cells.get("A3")?.put_value_string("Oranges")?;
        cells.get("B3")?.put_value_i32(8)?;
        cells.get("C3")?.put_value_bool(false)?;
    }
    workbook.save(&valid_path)?;

    let options = LoadOptions {
        try_repair_package: true,
        try_repair_xml: true,
        ..LoadOptions::default()
    };

    let loaded = Workbook::load_xlsx_with_options(&valid_path, &options)?;
    let sheet = loaded.worksheet("Sheet1")?;
    let cells = sheet.get_cells();

    println!("Saved: {}", valid_path.display());
    println!(
        "Loaded workbook with {} worksheet(s) and {} diagnostic issue(s).",
        loaded.get_worksheets().count(),
        loaded.get_load_diagnostics().issues().len()
    );
    println!("First item: {}", cells.get("A2")?.display_string_value());
    println!(
        "Second quantity: {}",
        cells.get("B3")?.display_string_value()
    );

    Ok(())
}

